#[verus::spec]
fn linear_search(nums: Vec<i32>, target: i32) -> i32 {
    // Precondition: nums is a vector of integers and target is an integer
    // Ensures: Returns the index of the target in nums if found, otherwise returns -1
    // Requires: nums.len() <= i32::MAX as we will return an i32 index
    // Ensures: If the target is found, the return value is the index of the target in nums
    // Ensures: If the target is not found, the return value is -1
    // Decreases: nums.len() (the length of the vector decreases with each iteration)
    
    let n = nums.len() as i32; // Length of the vector as i32
    let mut index = 0; // Initialize index

    // Invariant: 0 <= index <= n
    // This invariant holds true throughout the loop
    while index < n {
        // Assertion: At the start of each iteration, index is within bounds
        assert!(0 <= index && index < n);
        
        // Check if the current number matches the target
        if nums[index as usize] == target {
            return index; // Return the index as a 32-bit signed integer
        }
        
        index += 1; // Increment index
    }
    
    -1 // Return -1 if the target is not found
}